using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Windows.Forms;using System.Runtime.InteropServices;using Frociart;
internal static class ConsoleUiTests {
 static int checks;static MainForm main;static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static object Get(object o,string n){var f=o.GetType().GetField(n,F);return f==null?o.GetType().GetProperty(n,F).GetValue(o,null):f.GetValue(o);}
 static object Call(object o,string n,params object[] a){return o.GetType().GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);}
 static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
 static void Pump(int ms){var watch=System.Diagnostics.Stopwatch.StartNew();while(watch.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(3);}}
 static void Until(Func<bool> condition){for(int i=0;i<300;i++){if(condition())return;Pump(10);}throw new Exception("Native action timed out");}
 static FlowConsoleWindow Window {get{return(FlowConsoleWindow)Get(main,"runtimeConsole");}}
 static Control Find(Control c,string text){if(c.Text==text)return c;foreach(Control child in c.Controls){var found=Find(child,text);if(found!=null)return found;}return null;}
 static void CloseDetailWith(Action<Form> action,Action open){Exception failure=null;var timer=new Timer{Interval=25};timer.Tick+=delegate{var form=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f!=main&&f!=Window&&f.Visible);if(form==null)return;timer.Stop();try{action(form);}catch(Exception e){failure=e;form.Close();}};timer.Start();try{open();if(failure!=null)throw failure;}finally{timer.Stop();timer.Dispose();}}
 [STAThread]static int Main(string[] args){try{string root=args[0];Application.EnableVisualStyles();UiMotion.SetEnabled(true);main=new MainForm(null,true);main.Size=new Size(1250,900);main.Show();Pump(250);var doc=FlowPseudocode.Decode("DICHIARA nome: TESTO\nSTAMPA_CONTINUA \"Ciao \"\nLEGGI nome, \"Come ti chiami?\"\nSTAMPA nome\nLEGGI x, \"Quale numero?\"\nSTAMPA x+1");main.SetDocument(doc,null,false);((ComboBox)Get(main,"speed")).SelectedIndex=3;Call(main,"ShowRuntimeConsole");Pump(250);var window=Window;Check(window!=null&&window.Visible&&window.Messages.VirtualMode,"Real native console opens with virtual message list");Check(main.Runner!=null&&main.Runner.ConsoleLog.Count==0,"Opening alone never executes program");window.Step.PerformClick();Check(main.Runner.Steps==1,"Native Avanti advances exact program");window.Play.PerformClick();Until(()=>main.Runner.State==RuntimeState.WaitingForInput);window.RefreshState();Check(window.Input.Visible&&window.Input.AccessibleName.Contains("nome")&&!window.Play.Enabled,"Interactive input names actual variable");Check(window.ActiveControl==window.Input||window.Input.Focused,"Console input receives focus instead of hidden main field");window.Input.Text="Giulia";Check(((TextBox)Get(main,"inputValue")).Text=="Giulia","Pending text shared with main input");window.Send.PerformClick();Until(()=>main.Runner.State==RuntimeState.WaitingForInput&&main.Runner.InputVariable=="x");Until(()=>window.Send.Enabled);window.Input.Text="NaN";int count=main.Runner.ConsoleLog.Count;window.Send.PerformClick();Check(main.Runner.ConsoleLog.Count==count&&window.Input.Text=="NaN"&&((Label)Get(window,"error")).Text.Contains("finito"),"Invalid value remains editable and unrecorded");window.Input.Text="2";window.Send.PerformClick();window.Send.PerformClick();Until(()=>main.Runner.State==RuntimeState.Completed);window.RefreshState();Check(main.Runner.OutputText.Replace("\r\n","\n")=="Ciao Giulia\n3"&&main.Runner.ConsoleLog.Count==5,"Live console preserves original output and accepts each input once");Check(window.Messages.VirtualListSize==5&&!window.Input.Visible,"Native message list follows completed run");
  var report=new ExecutionSnapshot(doc,main.Runner);var inputs=report.Rows.SkipWhile(v=>v.Name!="VALORI INSERITI").Skip(1).ToList();Check(inputs.Count==2&&inputs[0].Name=="nome"&&inputs[0].Value=="Giulia"&&inputs[1].Name=="x"&&inputs[1].Value=="2"&&inputs.All(v=>v.Type.Contains("Principale")),"Image data includes accepted values and execution scope");using(var image=report.Render(main.Canvas)){ExecutionSnapshot.Save(image,Path.Combine(root,"console-diagram-data-pc.png"));Check(image.Width>=1280&&image.Height>300,"Actual legible diagram and input PNG rendered");}
  var same=main.Runner;Call(main,"ShowRuntimeConsole");Check(ReferenceEquals(same,main.Runner)&&ReferenceEquals(window,Window),"Reopen existing console retains completed evidence");string copied=null;window.ClipboardWrite=v=>copied=v;window.Copy.PerformClick();Check(copied==same.ConsoleLog.ToText()&&copied.Contains("LEGGI · nome")&&copied.Contains("Giulia"),"Copy exports actual retained chronology");window.Mode.SelectedIndex=1;Check(window.Plain.Visible&&window.Plain.Text.Replace("\r\n","\n")==copied,"Native text mode matches copied data");var path=Path.Combine(root,"native-console.txt");FlowConsoleWindow.WriteText(path,window.ExportText);Check(File.ReadAllText(path)==copied,"Actual UTF-8 text export");FlowConsoleWindow.WriteText(path,"Sostituita\n🐢");Check(File.ReadAllText(path)=="Sostituita\n🐢","Explicit file replacement preserves Unicode");window.Mode.SelectedIndex=0;Pump(450);
  foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark);Pump(450);using(var image=new Bitmap(window.Width,window.Height)){window.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(Path.Combine(root,"console-pc-"+(dark?"dark":"light")+".png"));}Check(window.Copy.Visible&&window.Messages.Visible&&window.Messages.BackColor==Ui.Paper,"Console controls retain themed presentation");}
  window.Messages.SelectedIndices.Add(1);Check(window.Messages.SelectedEntry.Kind==FlowConsoleLog.EntryKind.Input,"Native row selection identifies accepted input");CloseDetailWith(form=>{var button=(Button)Find(form,"Copia valore");Check(button!=null&&button.Visible,"Full value detail available");button.PerformClick();Check(copied=="Giulia","Detail copies original value without labels");form.Close();},()=>Call(window,"OpenMessage",window.Messages.SelectedEntry));
  var target=window.Messages.SelectedEntry;CloseDetailWith(form=>{var button=(Button)Find(form,"Vai al blocco");Check(button!=null,"Native locate action available");button.PerformClick();},()=>Call(window,"OpenMessage",target));Pump(250);Check(window.IsDisposed&&Window==null&&main.Canvas.SelectedNodeId==target.NodeId&&ReferenceEquals(main.Runner,same),"Locate actual originating block without restarting execution");Call(main,"ShowRuntimeConsole");Pump(250);window=Window;window.ClipboardWrite=v=>copied=v;window.Messages.Focus();window.Messages.SelectedIndices.Add(1);var key=typeof(FlowConsoleWindow).GetMethod("ProcessCmdKey",F);var keyArgs=new object[]{new Message(),Keys.Control|Keys.C};Check((bool)key.Invoke(window,keyArgs)&&copied=="Giulia","Ctrl+C copies selected accepted value");keyArgs[1]=Keys.Control|Keys.A;Check((bool)key.Invoke(window,keyArgs)&&window.Mode.SelectedIndex==1&&window.Plain.SelectionLength==window.Plain.TextLength,"Ctrl+A exposes and selects full text history");window.Mode.SelectedIndex=0;
  window.ClipboardWrite=v=>{throw new ExternalException("Controlled clipboard contention");};window.Copy.PerformClick();Check(((Label)Get(window,"info")).Text.Contains("occupati")&&window.Copy.Enabled,"Copy failure is recoverable");window.ClipboardWrite=v=>copied=v;int steps=same.Steps;window.Clear.PerformClick();window.RefreshState();Check(same.ConsoleLog.Count==0&&same.OutputText.Replace("\r\n","\n")=="Ciao Giulia\n3"&&same.Steps==steps&&same.State==RuntimeState.Completed,"Svuota does not restart or alter results");Check(report.Rows.Any(v=>v.Name=="nome"&&v.Value=="Giulia"),"Captured image is immutable after clearing console");Check(!window.Copy.Enabled&&!window.Save.Enabled&&((Label)Get(window,"empty")).Visible,"Empty console has honest state");
  window.Play.PerformClick();Until(()=>main.Runner.State==RuntimeState.WaitingForInput);window.RefreshState();Check(!ReferenceEquals(main.Runner,same)&&main.Runner.ConsoleLog.Count==1,"Riprova creates a new runtime/log without stale messages");window.Input.Text="Bozza non inviata";window.Close();Check(!window.Enabled&&!window.IsDisposed,"Close begins fade before disposing");Until(()=>window.IsDisposed);Check(((TextBox)Get(main,"inputValue")).Text=="Bozza non inviata","Closing console preserves pending input");Call(main,"ShowRuntimeConsole");Pump(250);window=Window;Check(window.Input.Text=="Bozza non inviata","Reopen restores pending input");
  Call(main,"PauseRun");for(int i=0;i<5000;i++)main.Runner.ConsoleLog.Add(FlowConsoleLog.EntryKind.Output,"Messaggio "+i,null,null,"n",null,"Principale",i,true);window.RefreshState();Check(window.Messages.VirtualListSize==FlowConsoleLog.MaxEntries,"Large history virtualized and bounded");window.Messages.SelectedIndices.Add(1000);long selected=window.Messages.SelectedEntry.Sequence;for(int i=0;i<100;i++)main.Runner.ConsoleLog.Add(FlowConsoleLog.EntryKind.Output,"Nuovo "+i,null,null,"n",null,"Principale",i,true);window.RefreshState();Check(window.Messages.SelectedEntry!=null&&window.Messages.SelectedEntry.Sequence==selected,"Eviction preserves selected message identity");Check(((Label)Get(window,"info")).Text.Contains("precedenti rimossi"),"Retention disclosed in console");Check(new ExecutionSnapshot(doc,main.Runner).Rows.Any(v=>v.Value=="Non restano valori inseriti nella cronologia conservata."),"Image discloses when prior input history may have been evicted");UiMotion.SetEnabled(false);window.Mode.SelectedIndex=1;window.Mode.SelectedIndex=0;window.RefreshState();Check(window.Messages.Visible,"Reduced motion path keeps controls functional");
  main.SetDocument(FlowPseudocode.Decode("STAMPA 1"),null,false);Check(window.IsDisposed&&Window==null,"Changing project closes console before displaying another document");main.SetDocument(DiagramIO.CreateBlank(),null,false);main.Close();Console.WriteLine("CONSOLE_PC_UI PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);if(main!=null){main.SetDocument(DiagramIO.CreateBlank(),null,false);main.Close();}return 1;}}
}

